    private void gadgets()throws Exception{
        progress("freestanding gadgets, visibility controls and full-width windows");
        GadgetSidebar gadgets=(GadgetSidebar)find(v->v instanceof GadgetSidebar);
        List<String> enabled=store.gadgets();
        check(gadgets!=null&&gadgets.getBackground()==null,"Gadgets have no dock");
        ui(()->home.open("setting:page:sidebar"));
        tap(find(v->"Hide desktop gadgets".equals(v.getContentDescription())));
        await(()->gadgets.getVisibility()==View.GONE,"Settings hides the gadget layer");
        check(store.gadgets().equals(enabled),"Hiding keeps enabled gadgets and their data");
        tap(find(v->"Show desktop gadgets".equals(v.getContentDescription())));
        await(gadgets::isShown,"Settings restores the existing gadgets");
        tap(find(v->"Keep gadgets above windows".equals(v.getContentDescription())));
        check(store.prefs.getBoolean("sidebar_always_top",false),"Always on top applies to the gadget layer");
        DesktopWindow control=window("@control");
        ui(control::maximize);
        await(()->control.getWidth()==((View)control.getParent()).getWidth(),"Gadgets do not reserve window width");
        tap(find(v->"Keep gadgets above windows".equals(v.getContentDescription())));
        close("@control");
        ui(()->home.open("@gadgets"));
        await(()->find(v->"Search Gadget Gallery".equals(v.getContentDescription()))!=null,"Gadget Gallery remains available");
        close("@gadgets");
    }
