    private Uri put(Uri parent,String name,byte[] data,String mime)throws Exception{Uri uri=DocumentsContract.createDocument(getTargetContext().getContentResolver(),parent,mime,name);try(OutputStream output=getTargetContext().getContentResolver().openOutputStream(uri,"w")){output.write(data);}return uri;}
    private Uri named(Uri folder,String name)throws Exception{for(DocumentOps.Ref item:DocumentOps.children(getTargetContext(),folder,new DocumentOps.Cancel()))if(item.item.name.equals(name))return item.uri;throw new FileNotFoundException(name);}
    private boolean exists(Uri folder,String name){try{named(folder,name);return true;}catch(Exception ex){return false;}}
    private boolean canRead(Uri uri){try{DocumentOps.stat(getTargetContext(),uri,new DocumentOps.Cancel());return true;}catch(Exception ex){return false;}}
    private DocumentOps.Ref reference(Uri uri,Uri parent)throws Exception{return new DocumentOps.Ref(uri,parent,DocumentOps.stat(getTargetContext(),uri,new DocumentOps.Cancel()));}
