    private void tap(View view)throws Exception{tap(view,60);}
    private void tap(View view,long hold)throws Exception{check(view!=null,"Native touch target exists");await(()->home.hasWindowFocus(),"Native window has focus before tapping");ui(()->view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),true));Rect bounds=new Rect();check(view.isEnabled()&&view.getGlobalVisibleRect(bounds)&&!bounds.isEmpty(),"Native target has visible touch bounds: "+view.getContentDescription());long now=SystemClock.uptimeMillis();input(now,MotionEvent.ACTION_DOWN,bounds.exactCenterX(),bounds.exactCenterY());Thread.sleep(hold);input(now,MotionEvent.ACTION_UP,bounds.exactCenterX(),bounds.exactCenterY());Thread.sleep(180);}
    private void input(long down,int action,float x,float y){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(event,true),"Physical input accepted");event.recycle();}
    private void setText(String description,String text)throws Exception{awaitNode(description);Bundle value=new Bundle();value.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,text);check(node(description).performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,value),"Text enters the real editable field: "+description);Thread.sleep(100);}
    private void menuTap(String text)throws Exception{awaitNode(text);getUiAutomation().waitForIdle(150,3000);AccessibilityNodeInfo node=node(text);check(node!=null&&node.isEnabled(),"Menu command is enabled: "+text);Rect bounds=new Rect();node.getBoundsInScreen(bounds);check(!bounds.isEmpty(),"Menu has touch bounds: "+text);long now=SystemClock.uptimeMillis();input(now,MotionEvent.ACTION_DOWN,bounds.exactCenterX(),bounds.exactCenterY());Thread.sleep(60);input(now,MotionEvent.ACTION_UP,bounds.exactCenterX(),bounds.exactCenterY());Thread.sleep(180);}
    private void awaitNode(String text)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){if(node(text)!=null)return;Thread.sleep(80);}throw new AssertionError("System/menu control: "+text);}
    private AccessibilityNodeInfo node(String text){return node(getUiAutomation().getRootInActiveWindow(),text);}
    private AccessibilityNodeInfo node(AccessibilityNodeInfo node,String text){if(node==null)return null;if(text.contentEquals(node.getText()==null?"":node.getText())||text.contentEquals(node.getContentDescription()==null?"":node.getContentDescription()))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo result=node(node.getChild(i),text);if(result!=null)return result;}return null;}
    private View find(Predicate<View> match){return find(root,match);}private View find(View view,Predicate<View> match){if(view==null||!view.isShown())return null;if(match.test(view))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View result=find(((ViewGroup)view).getChildAt(i),match);if(result!=null)return result;}return null;}
    private void ui(Runnable action){
        FutureTask<Void> task=new FutureTask<>(()->{action.run();return null;});home.runOnUiThread(task);
        try{task.get(15,TimeUnit.SECONDS);Thread.sleep(90);}
        catch(ExecutionException error){throw new AssertionError("UI action failed",error.getCause());}
        catch(InterruptedException error){Thread.currentThread().interrupt();throw new AssertionError(error);}
        catch(TimeoutException error){throw new AssertionError("UI action did not finish within 15 seconds",error);}
    }
    private void await(BooleanSupplier condition,String message)throws Exception{long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){boolean[] ready={false};runOnMainSync(()->ready[0]=condition.getAsBoolean());if(ready[0])return;Thread.sleep(100);}throw new AssertionError(message);}
