    private void shot(String name)throws Exception{
        Thread.sleep(200);Bitmap[] rendered={null};
        ui(()->{rendered[0]=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(rendered[0]));});
        Bitmap image=rendered[0];check(image!=null,"Native app render available");
        try(FileOutputStream out=getTargetContext().openFileOutput(name,0)){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}
    }
    private void dump(AccessibilityNodeInfo node,StringBuilder out,int depth){if(node==null||depth>24)return;Rect bounds=new Rect();node.getBoundsInScreen(bounds);out.append(depth).append(' ').append(node.getText()).append(" / ").append(node.getContentDescription()).append(" ").append(bounds).append('\n');for(int i=0;i<node.getChildCount();i++)dump(node.getChild(i),out,depth+1);}
